class Input {
    private static final InputStream INPUT = new BufferedInputStream(System.in);
    private static final byte[] BUFFER = new byte[1 << 16];
    private static int bufferPointer;
    private static int bytesRead;

    private static int read() throws IOException {
        if (bufferPointer >= bytesRead) {
            bytesRead = INPUT.read(BUFFER);
            bufferPointer = 0;

            if (bytesRead == -1) {
                return -1;
            }
        }

        return BUFFER[bufferPointer++];
    }

    public static String next() throws IOException {
        StringBuilder value = new StringBuilder();
        int c;

        do {
            c = read();
        } while (c <= ' ' && c != -1);

        if (c == -1) {
            return null;
        }

        while (c > ' ') {
            value.append((char) c);
            c = read();
        }

        return value.toString();
    }

    public static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public static int[] arrayInt(int length) throws IOException {
        int[] values = new int[length];

        for (int i = 0; i < length; i++) {
            values[i] = nextInt();
        }

        return values;
    }

    public static long[] arrayLong(int length) throws IOException {
        long[] values = new long[length];

        for (int i = 0; i < length; i++) {
            values[i] = nextLong();
        }

        return values;
    }

    public static int[][] getMatrix(int rows, int cols) throws IOException {
